FString SaveFileName = "SaveGame";

void SaveGame()
{
    USaveGame* SaveGameInstance = UGameplayStatics::CreateSaveGameObject(USaveGame::StaticClass());
    SaveGameInstance->SetSaveFileName(SaveFileName);
    SaveGameInstance->SetPlayerHealth(Health);
    SaveGameInstance->SetCurrentLevel(CurrentLevel);
    UGameplayStatics::SaveGameToSlot(SaveGameInstance, SaveFileName, 0);
}

void LoadGame()
{
    USaveGame* SaveGameInstance = UGameplayStatics::LoadGameFromSlot(SaveFileName, 0);
    if (SaveGameInstance)
    {
        Health = SaveGameInstance->GetPlayerHealth();
        CurrentLevel = SaveGameInstance->GetCurrentLevel();
    }
}
